const fs = require('fs');
const path = require('path');
const http = require('http');

const ENDPOINT = 'http://127.0.0.1:63963/status';
const OUTPUT = path.join(__dirname, 'results', 'status.json');

http.get(ENDPOINT, (res) => {
  let body = '';
  res.on('data', (chunk) => {
    body += chunk;
  });
  res.on('end', () => {
    const parsed = JSON.parse(body);
    fs.mkdirSync(path.dirname(OUTPUT), { recursive: true });
    fs.writeFileSync(OUTPUT, JSON.stringify({ status: parsed.status }, null, 2) + '\n');
    console.log('wrote', OUTPUT, parsed.status);
  });
}).on('error', (err) => {
  console.error(err.message);
  process.exit(1);
});

